import assert from 'node:assert/strict';
import {test} from 'node:test';
import {setTimeout as delay} from 'node:timers/promises';
import {readGcsVersionedContent} from '../site/gcs-versioned-content.mjs';

const generation = '9007199254740993';
const metageneration = '9007199254740995';
const body = Buffer.from('123456789');
// Independent standard checksum vector, not generated by the transport.
const crc32c = '4waSgw==';
const contentCid = 'sha256:15e2b0d3c33891ebb0f1ef609ec419420c20e320ce94c65fbc8c3312448eb225';
const scope = Object.freeze({operation: 'gcs:file:read',
  resourceOrigin: 'https://storage.googleapis.com', siteGeneration: 1,
  issuerAuthority: 'fixture-issuer', principal: 'fixture-principal',
  namespaceId: 'fixture-namespace', environment: 'fixture', siteKey: 'site',
  runtimeBundleCid: 'fixture-runtime', connectorRegistration: 'fixture-gcs',
  connectorRevision: 'fixture-revision', runInvocationCid: 'fixture-run',
  taskAttempt: 'original-attempt', dispatchRequestCid: 'fixture-dispatch'});
const auth = (useId, overrides = {}) => ({grant: {}, useId,
  scope: {...scope, ...overrides}});

function fixture({metadata = {}, media = body, metadataResponse = {},
  mediaResponse = {}, target = {}, limits = {}} = {}) {
  const state = {calls: [], charges: [], verificationBytes: [], handoffs: [], authCalls: [], events: []};
  const selected = {bucket: 'actql-fixture', prefix: 'fixture/',
    objectName: 'fixture/e\u0301%2F.json', generation, ...target};
  const originalMetadata = {bucket: selected.bucket, name: selected.objectName,
    generation, metageneration, size: '9', contentType: 'application/json',
    crc32c, ...metadata};
  const options = {target: selected,
    limits: {maxMetadataBytes: 4096, maxContentBytes: 9,
      maxRequestBytes: 4096, maxAttempts: 2, maxTimeMs: 1000, ...limits},
    initialAuthorization: auth('metadata'), credential: {journal: {fixture: true}},
    authorizationForRequest: async request => {
      state.authCalls.push(request.phase);
      return auth(request.phase);
    },
    recheckAuthorization: async () => {
      state.authCalls.push('handoff');
      return auth('handoff');
    },
    callResource: async invocation => {
      const request = invocation.operations.get(scope.operation);
      state.calls.push(invocation);
      state.events.push(`get:${state.calls.length}`);
      assert.equal(invocation.returnRejectedResponse, true);
      assert.equal(request.method, 'GET');
      assert.deepEqual(request.headers, [['accept-encoding', 'identity']]);
      assert.equal(request.body, undefined);
      const mediaRead = state.calls.length === 2;
      return {accepted: true, statusCode: 200, headers: [],
        useCid: `fixture-use-${state.calls.length}`,
        body: mediaRead ? media : Buffer.from(JSON.stringify(originalMetadata)),
        ...(mediaRead ? mediaResponse : metadataResponse)};
    },
    chargeBody: async (bytes, observation) => {
      const ticket = {phase: observation.phase, bytes: Buffer.from(bytes),
        useCid: observation.useCid};
      state.charges.push(ticket);
      state.events.push(`charge:${observation.phase}`);
      return ticket;
    },
    chargeVerification: async bytes => { state.verificationBytes.push(bytes); },
    receiveContent: async (bytes, observation) => {
      state.handoffs.push({bytes: Buffer.from(bytes), observation});
      state.events.push('handoff');
      return 'fixture-capture-ticket';
    }};
  return {options, state, originalMetadata};
}

test('exact stored bytes use generation and metageneration without normalization', async () => {
  const {options, state} = fixture();
  const result = await readGcsVersionedContent(options);
  assert.equal(result.receipt, 'fixture-capture-ticket');
  assert.equal(result.digests.contentCid, contentCid);
  assert.equal(result.metadata.generation, generation);
  assert.equal(result.metadata.metageneration, metageneration);
  assert.equal(result.metadata.objectName, 'fixture/e\u0301%2F.json');
  assert.equal(result.metadata.sizeBytes, 9n);
  assert.deepEqual(state.handoffs[0].bytes, body);
  assert.equal(state.handoffs[0].observation.metadataCharge, state.charges[0]);
  assert.equal(state.handoffs[0].observation.contentCharge, state.charges[1]);
  assert.deepEqual(state.verificationBytes, [9]);
  assert.deepEqual(state.authCalls, ['media', 'handoff']);
  assert.deepEqual(state.events, ['get:1', 'charge:metadata', 'get:2',
    'charge:media', 'handoff']);
  const paths = state.calls.map(call => call.operations.get(scope.operation).path);
  assert.deepEqual(paths, [
    '/storage/v1/b/actql-fixture/o/fixture%2Fe%CC%81%252F.json?generation=9007199254740993&ifGenerationMatch=9007199254740993',
    '/storage/v1/b/actql-fixture/o/fixture%2Fe%CC%81%252F.json?generation=9007199254740993&ifGenerationMatch=9007199254740993&alt=media&ifMetagenerationMatch=9007199254740995',
  ]);
});

test('typed empty content retains its exact empty checksum and size', async () => {
  const {options, state} = fixture({metadata: {size: '0', crc32c: 'AAAAAA=='},
    media: Buffer.alloc(0), limits: {maxContentBytes: 0}});
  const result = await readGcsVersionedContent(options);
  assert.equal(result.digests.contentCid,
    'sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
  assert.equal(result.metadata.sizeBytes, 0n);
  assert.equal(state.handoffs[0].bytes.length, 0);
  assert.equal(state.calls.length, 2);
});

for (const [name, change] of [
  ['generation', {generation: '9007199254740992'}],
  ['numeric generation', {generation: 9007199254740992}],
  ['foreign bucket', {bucket: 'other-bucket'}],
  ['normalized object name', {name: 'fixture/é%2F.json'}],
  ['missing metageneration', {metageneration: undefined}],
  ['imprecise size', {size: 9}],
  ['oversized object', {size: '9007199254740993'}],
]) {
  test(`metadata ${name} mismatch is charged and prevents media I/O`, async () => {
    const {options, state} = fixture({metadata: change});
    await assert.rejects(readGcsVersionedContent(options), {code: 'GcsContentMetadataMismatch'});
    assert.equal(state.calls.length, 1);
    assert.equal(state.charges.length, 1);
    assert.equal(state.handoffs.length, 0);
  });
}

for (const [name, change, expectedCalls] of [
  ['gzip metadata', {metadata: {contentEncoding: 'gzip'}}, 1],
  ['gzip media', {mediaResponse: {headers: [['content-encoding', 'gzip']]}}, 2],
  ['range media', {mediaResponse: {headers: [['content-range', 'bytes 0-8/10']]}}, 2],
]) {
  test(`${name} refuses representation without decompression or handoff`, async () => {
    const {options, state} = fixture(change);
    await assert.rejects(readGcsVersionedContent(options), {code: 'GcsContentRepresentationUnsupported'});
    assert.equal(state.calls.length, expectedCalls);
    assert.equal(state.charges.length, expectedCalls);
    assert.deepEqual(state.verificationBytes, []);
    assert.equal(state.handoffs.length, 0);
  });
}

test('metageneration conflict never retries or falls back to latest', async () => {
  const {options, state} = fixture({mediaResponse: {accepted: false,
    statusCode: 412, body: Buffer.from('conflict') }});
  await assert.rejects(readGcsVersionedContent(options), {code: 'GcsContentResourceRejected'});
  assert.equal(state.calls.length, 2);
  assert.equal(state.charges.length, 2);
  assert.equal(state.handoffs.length, 0);
});

for (const [name, change, code] of [
  ['wrong bytes', {media: Buffer.from('123456788')}, 'GcsContentDigestMismatch'],
  ['truncated bytes', {media: Buffer.from('12345678')}, 'GcsContentSizeMismatch'],
  ['partial status', {mediaResponse: {statusCode: 206}}, 'GcsContentResourceRejected'],
  ['wrong generation header', {mediaResponse: {headers: [['x-goog-generation', '7']]}}, 'GcsContentMetadataMismatch'],
  ['wrong metageneration header', {mediaResponse: {headers: [['x-goog-metageneration', '7']]}}, 'GcsContentMetadataMismatch'],
  ['wrong metadata metageneration header', {metadataResponse: {headers: [['x-goog-metageneration', '7']]}}, 'GcsContentMetadataMismatch'],
  ['invalid digest', {metadata: {crc32c: 'not-a-hash'}}, 'InvalidGcsContentDigest'],
  ['missing digest', {metadata: {crc32c: undefined}}, 'InvalidGcsContentDigest'],
  ['wrong MD5', {metadata: {md5Hash: 'AAAAAAAAAAAAAAAAAAAAAA=='}}, 'GcsContentDigestMismatch'],
]) {
  test(`${name} retains received byte charges and issues no content`, async () => {
    const {options, state} = fixture(change);
    await assert.rejects(readGcsVersionedContent(options), {code});
    assert.equal(state.handoffs.length, 0);
    assert.equal(state.charges.length, state.calls.length);
    if (name === 'partial status') {
      assert.equal(state.calls.length, 2);
      assert.deepEqual(state.verificationBytes, []);
    }
  });
}

test('authorization changed after metadata refuses before the second request', async () => {
  const {options, state} = fixture();
  options.authorizationForRequest = async () => auth('media', {connectorRevision: 'new'});
  await assert.rejects(readGcsVersionedContent(options), {code: 'InvalidGcsContentAuthorization'});
  assert.equal(state.calls.length, 1);
  assert.equal(state.charges.length, 1);
  assert.equal(state.handoffs.length, 0);
});

test('authorization changed after content refuses byte handoff', async () => {
  const {options, state} = fixture();
  options.recheckAuthorization = async () => auth('handoff', {principal: 'foreign'});
  await assert.rejects(readGcsVersionedContent(options), {code: 'InvalidGcsContentAuthorization'});
  assert.equal(state.calls.length, 2);
  assert.equal(state.charges.length, 2);
  assert.equal(state.handoffs.length, 0);
});

test('aborted after metadata accounting retains the ticket with no media request', async () => {
  const {options, state} = fixture();
  const controller = new AbortController();
  options.signal = controller.signal;
  const original = options.chargeBody;
  options.chargeBody = async (...args) => {
    const ticket = await original(...args);
    controller.abort(new Error('FixtureCancelled'));
    return ticket;
  };
  await assert.rejects(readGcsVersionedContent(options), /FixtureCancelled/u);
  assert.equal(state.calls.length, 1);
  assert.equal(state.charges.length, 1);
  assert.equal(state.handoffs.length, 0);
});

test('transport uncertainty is not retried and cannot complete capture', async () => {
  const {options, state} = fixture();
  const original = options.callResource;
  options.callResource = async call => {
    const result = await original(call);
    if (state.calls.length === 2) throw new Error('FixtureTransportUnknown');
    return result;
  };
  await assert.rejects(readGcsVersionedContent(options), /FixtureTransportUnknown/u);
  assert.equal(state.calls.length, 2);
  assert.equal(state.charges.length, 1);
  assert.equal(state.handoffs.length, 0);
});

for (const [name, change] of [
  ['missing version', options => { options.target.generation = undefined; }],
  ['foreign prefix', options => { options.target.prefix = 'elsewhere/'; }],
  ['unpaired surrogate', options => { options.target.objectName = 'fixture/\ud800'; }],
  ['attempt ceiling', options => { options.limits.maxAttempts = 1; }],
  ['missing charge owner', options => { options.chargeBody = undefined; }],
  ['missing verification owner', options => { options.chargeVerification = undefined; }],
]) {
  test(`${name} is rejected before credential use`, async () => {
    const {options, state} = fixture();
    change(options);
    await assert.rejects(readGcsVersionedContent(options), {code: 'InvalidGcsContentRead'});
    assert.equal(state.calls.length, 0);
    assert.equal(state.charges.length, 0);
  });
}

test('handoff failure preserves both existing-owner charge tickets', async () => {
  const {options, state} = fixture();
  options.receiveContent = async () => { throw new Error('FixtureCapturePending'); };
  await assert.rejects(readGcsVersionedContent(options), /FixtureCapturePending/u);
  assert.equal(state.calls.length, 2);
  assert.equal(state.charges.length, 2);
});

test('matching optional MD5 retains the same byte CID', async () => {
  // MD5 hex: 25f9e794323b453885f5181f1b624d0b, independently encoded.
  const {options} = fixture({metadata: {md5Hash: 'JfnnlDI7RTiF9RgfG2JNCw=='}});
  assert.equal((await readGcsVersionedContent(options)).digests.contentCid, contentCid);
});

test('verification budget failure retains charges and refuses capture', async () => {
  const {options, state} = fixture();
  options.chargeVerification = async bytes => {
    state.verificationBytes.push(bytes);
    throw Object.assign(new Error('FixtureWorkBudget'), {code: 'FixtureWorkBudget'});
  };
  await assert.rejects(readGcsVersionedContent(options), {code: 'FixtureWorkBudget'});
  assert.deepEqual(state.verificationBytes, [9]);
  assert.equal(state.charges.length, 2);
  assert.equal(state.handoffs.length, 0);
});

test('a missing byte charge ticket cannot advance to the second request', async () => {
  const {options, state} = fixture();
  options.chargeBody = async () => undefined;
  await assert.rejects(readGcsVersionedContent(options), {code: 'GcsContentChargeMissing'});
  assert.equal(state.calls.length, 1);
  assert.equal(state.handoffs.length, 0);
});

test('the transport timeout aborts I/O without retries or handoff', async () => {
  const {options, state} = fixture({limits: {maxTimeMs: 20}});
  const original = options.callResource;
  options.callResource = async call => {
    await original(call);
    await delay(1000, undefined, {signal: call.signal});
  };
  await assert.rejects(readGcsVersionedContent(options), {name: 'AbortError'});
  assert.equal(state.calls.length, 1);
  assert.equal(state.handoffs.length, 0);
});

test('mutating caller options across await cannot redirect the pinned read', async () => {
  const {options, state} = fixture();
  const original = options.callResource;
  options.callResource = async call => {
    const response = await original(call);
    options.target.generation = '7';
    options.target.objectName = 'outside/scope';
    options.limits.maxContentBytes = 0;
    options.credential.journal = {foreign: true};
    return response;
  };
  const result = await readGcsVersionedContent(options);
  assert.equal(result.metadata.generation, generation);
  assert.equal(result.metadata.objectName, 'fixture/e\u0301%2F.json');
  assert.equal(state.calls[1].maxResponseBytes, 9);
  assert.equal(state.calls[1].journal.fixture, true);
});

test('positive verification followed by cancellation does not hand off partial content', async () => {
  const {options, state} = fixture({media: Buffer.alloc(8193),
    metadata: {size: '8193'}, limits: {maxContentBytes: 8193}});
  const controller = new AbortController();
  options.signal = controller.signal;
  options.chargeVerification = async bytes => {
    state.verificationBytes.push(bytes);
    if (state.verificationBytes.length === 2) {
      controller.abort(new Error('FixtureStoppedAfterPositiveVerification'));
    }
  };
  await assert.rejects(readGcsVersionedContent(options), /FixtureStoppedAfterPositiveVerification/u);
  assert.deepEqual(state.verificationBytes, [4096, 4096]);
  assert.equal(state.charges.length, 2);
  assert.equal(state.handoffs.length, 0);
});
